/**
 * Embedded orchestration fixture helpers for `@vizij/orchestrator-wasm`.
 *
 * The generated bundle keeps orchestration descriptors, referenced graph specs, and animation
 * payloads available inside the published package for tests and example flows.
 */
import bundle from "./generated/fixtures-bundle.js";
const manifest = bundle.manifest;
const files = bundle.files;
function animationsMap() {
    return (manifest.animations ?? {});
}
function nodeGraphMap() {
    return (manifest["node-graphs"] ?? {});
}
function orchestrationMap() {
    return (manifest.orchestrations ?? {});
}
function normalizeRelPath(relPath) {
    return relPath.replace(/^[.][\\/]/, "").replace(/\\/g, "/");
}
function readFixture(relPath) {
    const normalized = normalizeRelPath(relPath);
    const raw = files[normalized];
    if (typeof raw !== "string") {
        throw new Error(`Fixture '${relPath}' was not embedded in this build`);
    }
    return raw;
}
function loadFixture(relPath) {
    return JSON.parse(readFixture(relPath));
}
function animationEntry(name) {
    const rel = animationsMap()[name];
    if (!rel) {
        throw new Error(`Unknown animation fixture: ${name}`);
    }
    return rel;
}
function nodeGraphEntry(name) {
    const value = nodeGraphMap()[name];
    if (!value || typeof value !== "object" || typeof value.spec !== "string") {
        throw new Error(`Unknown node-graph fixture: ${name}`);
    }
    return value;
}
function orchestrationEntry(name) {
    const value = orchestrationMap()[name];
    if (!value || (typeof value !== "string" && typeof value !== "object")) {
        throw new Error(`Unknown orchestration fixture: ${name}`);
    }
    return value;
}
function orchestrationRelPath(name) {
    const entry = orchestrationEntry(name);
    if (typeof entry === "string") {
        return entry;
    }
    if (entry && typeof entry === "object" && typeof entry.path === "string") {
        return entry.path;
    }
    throw new Error(`Orchestration entry '${name}' did not provide a descriptor path`);
}
export async function loadAnimationFixture(name) {
    return loadFixture(animationEntry(name));
}
function cloneStage(entries) {
    if (!entries)
        return [];
    return entries.map((entry) => ({ ...entry }));
}
function normalizeAnimationSeeds(seeds) {
    return (seeds ?? []).map((seed) => typeof seed === "string"
        ? { fixture: seed }
        : seed);
}
function normalizeGraphSeeds(seeds) {
    return (seeds ?? []).map((seed) => typeof seed === "string"
        ? { fixture: seed, mirrorWrites: false, stage: [] }
        : {
            fixture: seed.fixture,
            id: seed.id,
            subs: seed.subs,
            mirrorWrites: seed.mirrorWrites ?? false,
            stage: cloneStage(seed.stage),
        });
}
function normalizeMergedGraphSeeds(seeds) {
    return (seeds ?? []).map((seed) => ({
        id: seed.id,
        graphs: normalizeGraphSeeds(seed.graphs),
        strategy: seed.strategy ?? {},
    }));
}
function toMergeStrategy(value, field, name) {
    if (!value)
        return "error";
    const normalized = value.toLowerCase();
    if (normalized === "error")
        return "error";
    if (normalized === "namespace")
        return "namespace";
    if (normalized === "blend" || normalized === "blend-equal-weights" || normalized === "blend_equal_weights" || normalized === "blend_equal") {
        return "blend";
    }
    if (normalized === "add" ||
        normalized === "sum" ||
        normalized === "blend_sum" ||
        normalized === "blend-sum" ||
        normalized === "additive") {
        return "add";
    }
    if (normalized === "default-blend" ||
        normalized === "default_blend" ||
        normalized === "blend-default" ||
        normalized === "blend_weights" ||
        normalized === "blend-weights" ||
        normalized === "weights") {
        return "default-blend";
    }
    throw new Error(`Orchestration '${name}' provided unknown merge strategy '${value}' for ${field}`);
}
function asGraphSubscriptions(value) {
    if (!value || typeof value !== "object") {
        return undefined;
    }
    const record = value;
    const inputs = Array.isArray(record.inputs) ? record.inputs : undefined;
    const outputs = Array.isArray(record.outputs) ? record.outputs : undefined;
    const mirrorWrites = typeof record.mirrorWrites === "boolean" ? record.mirrorWrites : undefined;
    if (!inputs && !outputs && typeof mirrorWrites === "undefined") {
        return undefined;
    }
    return {
        inputs,
        outputs,
        mirrorWrites,
    };
}
export async function loadNodeGraphConfig(name) {
    const raw = loadFixture(nodeGraphEntry(name).spec);
    if (raw && typeof raw === "object") {
        const record = raw;
        if ("spec" in record && record.spec && typeof record.spec === "object") {
            const config = {
                spec: record.spec,
            };
            if (typeof record.id === "string" && record.id.length > 0) {
                config.id = record.id;
            }
            const subs = asGraphSubscriptions(record.subs);
            if (subs) {
                config.subs = subs;
            }
            return config;
        }
        if ("nodes" in record) {
            return {
                spec: record,
            };
        }
    }
    throw new Error(`Node-graph fixture '${name}' did not contain a GraphSpec-compatible payload`);
}
export async function loadNodeGraphSpec(name) {
    return loadNodeGraphConfig(name);
}
/** List orchestration fixture keys available via the embedded manifest. */
export async function listOrchestrationFixtures() {
    return Object.keys(orchestrationMap());
}
/** Load the raw descriptor JSON value for the given orchestration fixture key. */
export async function loadOrchestrationDescriptor(name) {
    return loadFixture(orchestrationRelPath(name));
}
/** Load the orchestration descriptor as a JSON string. */
export async function loadOrchestrationJson(name) {
    return readFixture(orchestrationRelPath(name));
}
function mergeSubscriptions(base, override, mirrorWrites) {
    const subs = {
        inputs: base?.inputs ? [...base.inputs] : undefined,
        outputs: base?.outputs ? [...base.outputs] : undefined,
        mirrorWrites,
    };
    if (override?.inputs)
        subs.inputs = [...override.inputs];
    if (override?.outputs)
        subs.outputs = [...override.outputs];
    if (typeof override?.mirrorWrites === "boolean") {
        subs.mirrorWrites = override.mirrorWrites;
    }
    return subs;
}
async function loadGraphBinding(seed) {
    const baseConfig = await loadNodeGraphConfig(seed.fixture);
    const config = {
        ...baseConfig,
        spec: baseConfig.spec,
    };
    if (seed.id) {
        config.id = seed.id;
    }
    const mergedSubs = mergeSubscriptions(baseConfig.subs, seed.subs, seed.mirrorWrites);
    if (mergedSubs.inputs || mergedSubs.outputs || typeof mergedSubs.mirrorWrites === "boolean") {
        config.subs = mergedSubs;
    }
    return {
        key: seed.fixture,
        id: seed.id,
        config,
        mirrorWrites: mergedSubs.mirrorWrites ?? false,
        stage: cloneStage(seed.stage),
    };
}
async function loadMergedGraphBinding(seed) {
    if (!seed.graphs.length) {
        throw new Error(`Orchestration '${seed.id}' merged graph is missing component graphs`);
    }
    const graphs = await Promise.all(seed.graphs.map((graph) => loadGraphBinding(graph)));
    return {
        id: seed.id,
        graphs,
        strategy: {
            outputs: toMergeStrategy(seed.strategy.outputs, "outputs", seed.id),
            intermediate: toMergeStrategy(seed.strategy.intermediate, "intermediate", seed.id),
        },
    };
}
async function loadAnimationBinding(seed, index) {
    const normalized = typeof seed === "string"
        ? { fixture: seed }
        : seed;
    const animation = await loadAnimationFixture(normalized.fixture);
    const setup = normalized.setup ??
        {
            animation,
            player: normalized.player ?? {
                name: index === 0 ? "fixture-player" : `fixture-player-${index}`,
                loop_mode: "loop",
            },
            ...(normalized.instance ? { instance: normalized.instance } : {}),
        };
    return {
        key: normalized.fixture,
        id: normalized.id,
        animation,
        setup,
    };
}
export async function loadOrchestrationBundle(name) {
    const descriptor = await loadOrchestrationDescriptor(name);
    if (!descriptor || typeof descriptor !== "object") {
        throw new Error(`Orchestration descriptor '${name}' did not resolve to an object`);
    }
    const animations = normalizeAnimationSeeds(descriptor.animations);
    const graphs = normalizeGraphSeeds(descriptor.graphs);
    const mergedGraphs = normalizeMergedGraphSeeds(descriptor.mergedGraphs ??
        descriptor.merged_graphs);
    if (!animations.length) {
        throw new Error(`Orchestration '${name}' descriptor is missing animation references`);
    }
    if (!graphs.length && !mergedGraphs.length) {
        throw new Error(`Orchestration '${name}' descriptor is missing graph references`);
    }
    const animationBindings = await Promise.all(animations.map((seed, idx) => loadAnimationBinding(seed, idx)));
    const graphBindings = await Promise.all(graphs.map((seed) => loadGraphBinding(seed)));
    const mergedBindings = await Promise.all(mergedGraphs.map((seed) => loadMergedGraphBinding(seed)));
    const initialInputs = [
        ...(descriptor.initial_inputs ? cloneStage(descriptor.initial_inputs) : []),
        ...graphBindings.flatMap((binding) => cloneStage(binding.stage)),
        ...mergedBindings.flatMap((merged) => merged.graphs.flatMap((binding) => cloneStage(binding.stage))),
    ];
    return {
        descriptor,
        animations: animationBindings,
        graphs: graphBindings,
        mergedGraphs: mergedBindings,
        initialInputs,
    };
}
